<?php
declare(strict_types=1); namespace App\Services; use PDO;
final class PreRegistrationService { public function __construct(private readonly PDO $database) {} private function manager(string $r):void{if($r!=='informatica')throw new \DomainException('No autorizado.');}
 public function create(string $c,string $assigned,int $by,string $role):array{$this->manager($role);if(!preg_match('/^\d{10}$/',$c))throw new \InvalidArgumentException('Cédula inválida.');if(!in_array($assigned,['bienes_activos_fijos','contador','contratacion_publica','administrativo','financiero','medico','planificacion','informatica','talento_humano','comunicacion'],true))throw new \InvalidArgumentException('Rol inválido.');$s=$this->database->prepare('INSERT INTO pre_registrations (cedula,role_code,created_by) VALUES (?,?,?)');$s->execute([$c,$assigned,$by]);return['cedula'=>$c];}
 public function findPending(string $c):?array{$s=$this->database->prepare('SELECT cedula,role_code FROM pre_registrations WHERE cedula=? AND status="pendiente" AND is_active=1');$s->execute([$c]);return $s->fetch()?:null;}
 public function list(int $p,string $r):array{$this->manager($r);$p=max(1,$p);$total=(int)$this->database->query('SELECT COUNT(*) FROM pre_registrations')->fetchColumn();$s=$this->database->prepare('SELECT id,cedula,role_code,status,first_names,last_names,is_active,created_by,created_at FROM pre_registrations ORDER BY created_at DESC LIMIT 5 OFFSET ?');$s->bindValue(1,($p-1)*5,PDO::PARAM_INT);$s->execute();return['items'=>$s->fetchAll(),'page'=>$p,'total'=>$total,'pages'=>(int)ceil($total/5)];}
 public function toggle(int $id,string $r,string $ownCedula):void{$this->manager($r);$s=$this->database->prepare('SELECT cedula FROM pre_registrations WHERE id=?');$s->execute([$id]);if($s->fetchColumn()===$ownCedula)throw new \DomainException('No puede modificar su propio registro.');$this->database->prepare('UPDATE pre_registrations SET is_active=NOT is_active WHERE id=?')->execute([$id]);}
 public function complete(string $c,string $f,string $l):void{if(trim($f)===''||trim($l)==='')throw new \InvalidArgumentException('Complete nombres y apellidos.');$s=$this->database->prepare('UPDATE pre_registrations SET first_names=?,last_names=?,status="registrado" WHERE cedula=? AND is_active=1 AND status="pendiente"');$s->execute([trim($f),trim($l),$c]);if(!$s->rowCount())throw new \DomainException('Registro duplicado o no disponible.');}}
